import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
const t = (k, p) => app.translator.trans('ernestdefoe-millwright.admin.' + k, p);
const PHASES = ['plan', 'fetch', 'apply', 'finalise'];
/**
 * What is happening, while it happens.
 *
 * 🚨 This panel is the product. An update that works but shows a spinner is the
 * thing being replaced — the complaint that started all of this was not "it
 * failed", it was "the status has been showing running for a while and I don't
 * know what is going on". So every piece of state the server knows is on screen:
 * which phase, which item of how many, every line of the log, how long since
 * anything moved, and which driver is turning the handle.
 *
 * 🚨 It also never advertises progress it has not been told about. When a poll
 * comes back saying another driver holds the run, that is shown as exactly that
 * rather than as a stalled bar.
 */
export default class RunPanel extends Component {
  /** Consecutive failed polls. A host hiccup is not a failed update. */
  misses = 0;
  polling = false;
  rollingBack = false;
  oncreate(vnode) {
    super.oncreate(vnode);
    this.poll();
  }
  onremove() {
    // Stops the loop rescheduling itself once the page is gone.
    this.polling = false;
  }
  view() {
    const run = this.attrs.run;
    if (!run) return null;
    const failed = run.state === 'failed';
    const done = run.state === 'done';
    const rolled = run.state === 'rolled-back';
    return m("div", {
      className: 'Millwright-run' + (failed ? ' Millwright-run--failed' : '')
    }, m("div", {
      className: "Millwright-runHead"
    }, m("h3", null, done ? t('run_done') : rolled ? t('run_rolled_back') : failed ? t('run_failed') : t('run_working')), this.attrs.driver ? m("span", {
      className: "Millwright-driver"
    }, this.attrs.driver) : null), !done && !failed && !rolled ? this.phases(run) : null, !done && !failed && !rolled ? this.bar(run) : null, failed ? m("div", {
      className: "Millwright-error"
    }, m("div", {
      className: "Millwright-errorWhere"
    }, t('failed_at', {
      step: run.errorStep
    })), m("pre", {
      className: "Millwright-errorText"
    }, run.error), m("button", {
      className: "Button",
      disabled: this.rollingBack,
      onclick: () => this.rollback()
    }, this.rollingBack ? t('rolling_back') : t('roll_back'))) : null, this.attrs.rollbackNote ? m("div", {
      className: "Millwright-next"
    }, this.attrs.rollbackNote) : null, this.misses > 2 && !done && !failed && !rolled ? m("div", {
      className: "Millwright-stall"
    }, t('poll_failing', {
      count: this.misses
    })) : null, this.attrs.busy && !done && !failed && !rolled ? m("div", {
      className: "Millwright-stall"
    }, t('another_driver')) : null, this.attrs.stale && !done && !failed && !rolled ? m("div", {
      className: "Millwright-stall"
    }, t('nothing_moved')) : null, done || rolled || failed ? m("button", {
      className: "Button Button--link Millwright-dismiss",
      onclick: () => this.attrs.ondismiss()
    }, t('dismiss')) : null, m("ol", {
      className: "Millwright-log"
    }, (run.log || []).map((line, i) => m("li", {
      key: i
    }, line))));
  }
  phases(run) {
    const at = PHASES.indexOf(run.phase);
    return m("ol", {
      className: "Millwright-phases"
    }, PHASES.map((p, i) => m("li", {
      key: p,
      className: 'Millwright-phase' + (i < at ? ' is-done' : i === at ? ' is-now' : '')
    }, t('phase_' + p))));
  }
  bar(run) {
    const total = (run.items || []).length;
    const item = total ? run.items[Math.min(run.index, total - 1)] : null;
    return m("div", {
      className: "Millwright-progress"
    }, m("div", {
      className: "Millwright-progressBar"
    }, m("div", {
      className: "Millwright-progressFill",
      style: {
        width: (total ? Math.round(run.index / total * 100) : 0) + '%'
      }
    })), m("div", {
      className: "Millwright-progressText"
    }, total ? t('working_on', {
      item,
      index: Math.min(run.index + 1, total),
      total
    }) : t('working_out')));
  }
  poll() {
    if (this.polling) return;
    this.polling = true;
    this.tick();
  }
  tick() {
    if (!this.polling) return;
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/millwright/step'
    }).then(data => {
      this.misses = 0;
      this.attrs.onprogress(data);
      if (data.idle) {
        this.polling = false;
        this.attrs.ondone(data.run);
        return;
      }
      m.redraw();
      setTimeout(() => this.tick(), 1500);
    }).catch(() => {
      /*
       * 🚨 A failed poll is never a failed update, and this is the difference
       * between the two designs. The run's state is on disk; a 502 from a
       * host that cut the request means this one call did not land, and the
       * next one picks up where the last left off. Backing off keeps a
       * struggling host from being hammered while it recovers.
       */
      this.misses++;
      m.redraw();
      setTimeout(() => this.tick(), Math.min(1500 * this.misses, 15000));
    });
  }
  rollback() {
    this.rollingBack = true;
    this.polling = false;
    m.redraw();
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/millwright/rollback'
    }).then(data => {
      this.rollingBack = false;
      this.attrs.onrollback(data);
      m.redraw();
    }).catch(e => {
      this.rollingBack = false;
      this.attrs.onerror(e?.response?.error || t('rollback_failed'));
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-millwright', 'admin/components/RunPanel', RunPanel);